def parse_jsonl(filepath: str, chunk_size: int = 8192):
    """Memory-efficient JSONL parser using chunked reading."""
    import json
    buffer = ''
    with open(filepath, 'r') as f:
        while chunk := f.read(chunk_size):
            buffer += chunk
            while '\n' in buffer:
                line, buffer = buffer.split('\n', 1)
                if line.strip():
                    yield json.loads(line)
    if buffer.strip():
        yield json.loads(buffer)

# Usage
for record in parse_jsonl('data.jsonl'):
    process(record)
