# Before: God class doing everything
class DataProcessor:
    def __init__(self): self.data = []
    def load(self, f): self.data = json.load(open(f))
    def clean(self): self.data = [d for d in self.data if d.get('valid')]
    def transform(self): self.data = [{**d, 'processed': True} for d in self.data]
    def save(self, f): json.dump(self.data, open(f, 'w'))
    def stats(self): return len(self.data)

# After: Single responsibility, composable
from dataclasses import dataclass
from typing import Protocol

class Loader(Protocol):
    def load(self, path: str) -> list[dict]: ...

class Transformer(Protocol):
    def transform(self, data: list[dict]) -> list[dict]: ...

class Saver(Protocol):
    def save(self, data: list[dict], path: str) -> None: ...

@dataclass
class JSONLoader:
    def load(self, path: str) -> list[dict]:
        import json
        return json.load(open(path))

@dataclass
class ValidationCleaner:
    def transform(self, data: list[dict]) -> list[dict]:
        return [d for d in data if d.get('valid')]

@dataclass
class AddProcessedFlag:
    def transform(self, data: list[dict]) -> list[dict]:
        return [{**d, 'processed': True} for d in data]

@dataclass
class JSONSaver:
    def save(self, data: list[dict], path: str) -> None:
        import json
        json.dump(data, open(path, 'w'))

# Pipeline
class Pipeline:
    def __init__(self, loader: Loader, *transformers: Transformer, saver: Saver):
        self.loader, self.transformers, self.saver = loader, transformers, saver
    def run(self, in_path: str, out_path: str):
        data = self.loader.load(in_path)
        for t in self.transformers:
            data = t.transform(data)
        self.saver.save(data, out_path)

# Usage
Pipeline(JSONLoader(), ValidationCleaner(), AddProcessedFlag(), saver=JSONSaver())
    .run('input.json', 'output.json')
